// src/components/Dashboard.js
import React from 'react';

const Dashboard = () => {
  return (
    <div className="dashboard">
      <h2>Overview</h2>
      <div className="card">
        <h3>Statistics</h3>
        <p>Total users: 1200</p>
        <p>Revenue: $23,450</p>
      </div>
      <div className="card">
        <h3>Recent Activities</h3>
        <p>New user signups: 50</p>
      </div>
    </div>
  );
}

export default Dashboard;
